# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, offset=4):
    return [v - offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(render(fold(intake(raw))))

